            unassigned.append(c)

    def demand_of(i):
        if demands is None:
            return 0
        if isinstance(demands, dict):
            return demands.get(i, 0)
        if isinstance(demands, (list, tuple)) and isinstance(i, int) and 0 <= i < len(demands):
            return demands[i]
        return 0

    def point_of(i):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(i, None)
        if isinstance(coords, (list, tuple)) and isinstance(i, int) and 0 <= i < len(coords):
            return coords[i]
        return None

    def d(i, j):
        if dist_matrix is not None:
            if isinstance(dist_matrix, dict):
                row = dist_matrix.get(i, None)
                if isinstance(row, dict) and j in row:
                    return row[j]
                row = dist_matrix.get(j, None)
                if isinstance(row, dict) and i in row:
                    return row[i]
            elif isinstance(dist_matrix, (list, tuple)) and isinstance(i, int) and isinstance(j, int):
                return dist_matrix[i][j]
        if coords is not None:
            a = point_of(i)
            b = point_of(j)
            if a is not None and b is not None:
                return dist(a, b)
        return 0

    if capacity is None:
        capacity = 0
        for c in unassigned:
            dem = demand_of(c)
            if dem > 0:
                capacity += dem
        if capacity <= 0:
            capacity = 10 ** 18

    # order customers deterministically
    if coords is not None:
        depot_p = point_of(depot)
        if depot_p is None:
            depot_p = (0, 0)
        unassigned.sort(key=lambda c: (
            (point_of(c)[0] - depot_p[0]) ** 2 + (point_of(c)[1] - depot_p[1]) ** 2 if point_of(c) is not None else 0,
            demand_of(c),
            c
        ))
    else:
        unassigned.sort(key=lambda c: (-demand_of(c), c))

    # initial construction: best insertion into current open route, otherwise new route
    routes = []
    loads = []

    for c in unassigned:
        dem = demand_of(c)
        best_r = -1
        best_pos = -1
        best_inc = None

        for r_idx, route in enumerate(routes):
            if loads[r_idx] + dem > capacity:
                continue
            prev = depot
            for pos in range(len(route) + 1):
                nxt = depot if pos == len(route) else route[pos]
                inc = d(prev, c) + d(c, nxt) - d(prev, nxt)
                key = (inc, pos, r_idx)
                if best_inc is None or key < best_inc:
                    best_inc = key
                    best_r = r_idx
                    best_pos = pos
                prev = nxt

        if best_r == -1:
            routes.append([c])
            loads.append(dem)
        else:
            routes[best_r].insert(best_pos, c)
            loads[best_r] += dem

    def route_cost(route):
        if not route:
            return 0
        total = d(depot, route[0])
        for i in range(len(route) - 1):
            total += d(route[i], route[i + 1])
        total += d(route[-1], depot)
        return total

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    # intra-route 2-opt
    improved = True
    while improved:
        improved = False
        for r_idx, route in enumerate(routes):
            n = len(route)
            if n < 4:
                continue
            best_delta = 0
            best_i = best_j = None
            for i in range(n - 1):
                a = depot if i == 0 else route[i - 1]
                b = route[i]
                for j in range(i + 1, n):
                    c = route[j]
                    d2 = depot if j == n - 1 else route[j + 1]
                    delta = d(a, c) + d(b, d2) - d(a, b) - d(c, d2)
                    if delta < best_delta - 1e-12:
                        best_delta = delta
                        best_i, best_j = i, j
            if best_i is not None:
                route[best_i:best_j + 1] = reversed(route[best_i:best_j + 1])
                improved = True

    # inter-route relocate and swap
    improved = True
    while improved:
        improved = False

        # relocate best move
        best_move = None
        for i in range(len(routes)):
            ri = routes[i]
            li = loads[i]
            for pi, c in enumerate(ri):
                demc = demand_of(c)
                pre = depot if pi == 0 else ri[pi - 1]
                nxt = depot if pi == len(ri) - 1 else ri[pi + 1]
                remove_delta = d(pre, nxt) - d(pre, c) - d(c, nxt)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if loads[j] + demc > capacity:
                        continue
                    prev = depot
                    for pj in range(len(rj) + 1):
                        nxt2 = depot if pj == len(rj) else rj[pj]
                        insert_delta = d(prev, c) + d(c, nxt2) - d(prev, nxt2)
                        delta = remove_delta + insert_delta
                        if delta < -1e-12 and (best_move is None or (delta, i, pi, j, pj, c) < best_move):
                            best_move = (delta, i, pi, j, pj, c)
                        prev = nxt2

        if best_move is not None:
            _, i, pi, j, pj, c = best_move
            routes[j].insert(pj, c)
            loads[j] += demand_of(c)
            routes[i].pop(pi)
            loads[i] -= demand_of(c)
            if not routes[i]:
                routes.pop(i)
                loads.pop(i)
            improved = True
            continue

        # swap best move
        best_swap = None
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                for pi, a in enumerate(ri):
                    da = demand_of(a)
                    pre_a = depot if pi == 0 else ri[pi - 1]
                    nxt_a = depot if pi == len(ri) - 1 else ri[pi + 1]
                    rem_a = d(pre_a, nxt_a) - d(pre_a, a) - d(a, nxt_a)
                    for pj, b in enumerate(rj):
                        db = demand_of(b)
                        if loads[i] - da + db > capacity or loads[j] - db + da > capacity:
                            continue
                        pre_b = depot if pj == 0 else rj[pj - 1]
                        nxt_b = depot if pj == len(rj) - 1 else rj[pj + 1]
                        rem_b = d(pre_b, nxt_b) - d(pre_b, b) - d(b, nxt_b)
                        add_a = d(pre_b, a) + d(a, nxt_b) - d(pre_b, b) - d(b, nxt_b)
                        add_b = d(pre_a, b) + d(b, nxt_a) - d(pre_a, a) - d(a, nxt_a)
                        delta = rem_a + rem_b + add_a + add_b
                        if delta < -1e-12 and (best_swap is None or (delta, i, pi, j, pj, a, b) < best_swap):
                            best_swap = (delta, i, pi, j, pj)

        if best_swap is not None:
            _, i, pi, j, pj = best_swap
            a = routes[i][pi]
            b = routes[j][pj]
            routes[i][pi], routes[j][pj] = b, a
            loads[i] += demand_of(b) - demand_of(a)
            loads[j] += demand_of(a) - demand_of(b)
            improved = True

    return routes
